
/**
 * UDHAYA NILAVAN — HERO PORTRAIT + UN MARK
 *
 * One-file integration component.
 * It contains:
 *   1) The exact supplied portrait as an embedded PNG data URI.
 *   2) A vector UN monogram recreated from the supplied UN reference.
 *   3) The surrounding blueprint/doodle composition as inline SVG/CSS.
 *
 * ONLY integrate this into the existing Hero + existing UN logo locations.
 * Do not replace the rest of the portfolio.
 */

type HeroPortraitBlueprintProps = {
  className?: string;
  imageAlt?: string;
};

export type UNLogoMarkProps = {
  size?: number;
  className?: string;
  title?: string;
  color?: string;
};

const PORTRAIT_SRC = "data:image/png;base64,";

/* -------------------------------------------------------------------------- */
/* UN LOGO — recreated as an inline vector                                    */
/* -------------------------------------------------------------------------- */

export function UNLogoMark({
  size = 42,
  className = '',
  title = 'UN',
  color,
}: UNLogoMarkProps) {
  return (
    <span
      className={`un-inline-mark ${className}`}
      style={{ width: size, height: size, color: color || 'inherit' }}
      role="img"
      aria-label={title}
    >
      <svg
        viewBox="0 0 64 64"
        width="100%"
        height="100%"
        aria-hidden="true"
        focusable="false"
      >
        <path
          d="M8 10v26c0 10 7 17 17 17s17-7 17-17V18"
          fill="none"
          stroke="currentColor"
          strokeWidth="5.1"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M38 17v34"
          fill="none"
          stroke="currentColor"
          strokeWidth="5.1"
          strokeLinecap="round"
        />
        <path
          d="M38 17l19 25V12"
          fill="none"
          stroke="currentColor"
          strokeWidth="5.1"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M48 8h9"
          fill="none"
          stroke="currentColor"
          strokeWidth="5.1"
          strokeLinecap="square"
        />
      </svg>
    </span>
  );
}

